; ============================================================================
; AUDIO SYSTEM INITIALIZATION
; Main initialization routine for all audio subsystems:
;   - Inter-CPU communication setup
;   - Serial port ring buffers
;   - DSP chip configuration (dual DSPs at 0x00130000)
;   - Tone generator initialization (at 0x00110000)
; ============================================================================
Audio_System_Init:	; 01FACBh
	pushw iz
	call 0x20C15	; Setup inter-CPU comms via latches
	call 0x1F8DF	; Initialize serial port #1 ring buffers
	call 0x34C45	; Initialize DSP state buffers, toggle reset signals
	call 0x3581D	; Initialize DSP2 (second DSP chip)
	call 0x1FC95	; Write channel config to DSP at 0x00130000
	call 0x3D016	; Initialize tone generator at 0x00110000
	ei 0	; Enable interrupts

Audio_Main_Loop:
	bitda 5, 4158
	jr z, LABEL_01FAF0
	resda 5, 4158

LABEL_01FAF0:
	ldda32 xwa, 4160
	cp xwa, 0x3E8
	jr ule, LABEL_01FAFF
	dd82 0x38, 0xB8	; unmute (?) (here I'm assuming "MUTE" it is an active low signal)

LABEL_01FAFF:
	bitda 1, 4158
	jr z, LABEL_01FB2F
	resda 1, 4158
	call 0x20FBC
	call 0x34CDB
	ldda16 xwa, 61458
	ld bc, wa
	inc 1, wa
	stda16 61458, xwa
	cp bc, 0xA
	jr lt, LABEL_01FB29
	stdi16 61458, 0

LABEL_01FB29:
	cps iz, 0
	jr z, LABEL_01FB2F
	dec 1, iz

LABEL_01FB2F:
	call 0x3D01E
	call 0x34D93
	call 0x35AC8
	call 0x1F8D5
	jr Audio_Main_Loop


