	stda8 61460, a
	extz bc
	cps bc, 0
	jr mi, LABEL_01FBB8
	cps bc, 5
	jr gt, LABEL_01FBB8
	add bc, bc
	ldada_24 xix, 62560
	ld_bc_sriw3 0x07, 0xF0, 0xE4
	ldada_24 xix, 129910
