; ===========================================================================
; InterCPU_Latch_Setup - Setup inter-CPU communication via latches
; ===========================================================================
; Entry: None
; Exit:  DMA channels and interrupt handlers configured
; Notes: Configures interrupt priority for DMA channels 0-3
;        Sets up MicroDMA for inter-CPU latch communication at 0x120000
;        Initializes DMA_XFER_STATE and CMD_PROCESSING_STATE to 0
; ===========================================================================
InterCPU_Latch_Setup:
	sd8b3 0xE5, 0x3C, 0xF8
	dd82 0x80, 0xB2
	dd82 0xEC, 0x31
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	dd82 0xED, 0x31
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	dd82 0xF0, 0x31
	ld a, (xbc)
	and a, 0xF8
	set 0, a
	ld (xbc), a
	ldio 0x8A, 0x14
	ldada_24 xwa, 1179648
	ldc_cr32 xwa, 0x28
	ldb a, 0x8
	ldc_cr8 a, 0x4A
	ldada_24 xwa, 1179648
	ldc_cr32 xwa, 0x00
	ldb a, 0x0
	ldc_cr8 a, 0x42
	stdi8 4328, 0
	stdi8 4330, 0
	ret

; ===========================================================================
; InterCPU_DMA_Send - Send data via DMA to main CPU
; ===========================================================================
; Entry: XDE = source data pointer
;        BC = byte count
;        A = command/channel identifier
; Exit:  Data transferred to main CPU via inter-CPU latch
; Notes: Splits large transfers into 32-byte chunks
;        Used by tone generator and audio subsystem for command responses
; ===========================================================================
InterCPU_DMA_Send:
	dec 6, xsp
	pushw iz
	ld (xsp + 2), xde
	ld iz, bc
	ld (xsp + 6), a
	cp iz, 0x20
	jr ule, DMA_Send_Final

DMA_Send_Loop:
	ld a, (xsp + 6)
	extz wa
	ldw bc, 0x20
	ld xde, (xsp + 2)
	calr InterCPU_DMA_Send_Chunk
	ld xwa, 0x20
	add (xsp + 2), xwa
	sub iz, 0x20
	cp iz, 0x20
	jr ugt, DMA_Send_Loop

DMA_Send_Final:
	ld a, (xsp + 6)
	extz wa
	ldto_c_berp 0xF8
	extz bc
	ld xde, (xsp + 2)
	calr InterCPU_DMA_Send_Chunk
	popw iz
	inc 6, xsp
	ret

; ===========================================================================
; InterCPU_DMA_Send_Chunk - Transfer a single chunk of data to main CPU
; ===========================================================================
; Entry: XDE = source data pointer
;        BC = byte count (must be non-zero)
;        A = command/channel identifier (bits 7-5 used for dispatch)
; Exit:  Data transferred via DMA channel 2
; Notes: Helper for InterCPU_DMA_Send - handles one transfer operation.
;        Waits for MSTAT1 handshake, sets up DMA, then waits for completion.
;        Command byte format: (A << 5) | (length - 1)
; ===========================================================================
InterCPU_DMA_Send_Chunk:
	cps c, 0
	ret z
	lds ix, 0

DMA_Chunk_Start:
	dd82 0x34, 0xCC	; MSTAT1 - test if Main CPU is requesting handshake
	jr z, InterCPU_Wait_MSTAT1_Clear
	dd82 0x34, 0xB0	; SSTAT0 - clear to acknowledge Main CPU handshake request
	stdi8 4328, 1
	ld l, c
	dec 1, l
	sll a, 5
	or a, l
	stda8_24 1179648, a
	lds ix, 0

DMA_Chunk_Transfer:
	dd82 0x34, 0xCC	; MSTAT1 - wait for Main CPU to clear (data ready to receive)
	jr nz, InterCPU_Wait_MSTAT1_Set
	dd82 0x34, 0xB8	; SSTAT0 - set to signal ready to receive DMA data
	ldc_cr32 xde, 0x08
	extz bc
	ldc_cr16 bc, 0x48
	stdi8 258, 22
	dd82 0x80, 0xBA
	cpdi8 4328, 0
	ret z

DMA_Chunk_Wait:
	cpdi8 4328, 0
	jr nz, DMA_Chunk_Wait
	ret

InterCPU_Wait_MSTAT1_Clear:
	ld hl, ix
	inc 1, ix
	cp hl, 0xEA60
	jr ule, DMA_Chunk_Start
	ret

InterCPU_Wait_MSTAT1_Set:
	ld wa, ix
	inc 1, ix
	cp wa, 0xEA60
	jr ule, DMA_Chunk_Transfer
	dd82 0x34, 0xB8	; SSTAT0 - timeout recovery: force ready state before exit
	ret

