	stdi16 61466, 0
	stdi8 256, 0	; Stop DMA
	stdi8 4330, 0
	dd82 0x34, 0xB9	; SSTAT1 - timeout recovery: force ready state after DMA abort
	incdi8 1, 61464	; Increment error counter
	ret

