	ld a, (xiz + 3)
	res 7, a
	cps a, 0
	jr z, LABEL_02CFE7
	ld a, (xiz)
	and a, 0x8
	call 0x21036
	ld l, (xiz + 1)
	ld c, (xiz + 2)
	ld e, (xiz + 3)
	ld a, (xsp + 4)
	extz wa
	pushw wa
	ld a, l
	calr Voice_SetVelocity
	ld l, (xiz + 1)
	ld c, (xiz + 2)
	ld e, (xiz + 3)
	ld a, (xsp + 4)
	extz wa
	pushw wa
	ld a, l
	calr Voice_SetPitch
	jr LABEL_02D009

LABEL_02CFE7:
	ld a, (xiz + 1)
	ld c, (xiz + 2)
	calr Voice_Allocate
	ld xwa, xhl
	calr Voice_ParamInit
	ld l, (xiz + 1)
	ld c, (xiz + 2)
	ld e, (xiz + 3)
	ld a, (xsp + 4)
	extz wa
	pushw wa
	ld a, l
