; ===========================================================================
; RingBuf_ReadByte - Read single byte from audio ring buffer
; ===========================================================================
; Entry: XWA = pointer to buffer control structure:
;        +0 = read pointer (16-bit)
;        +2 = write pointer (16-bit)
;        +4 = byte count (16-bit)
;        +6 = buffer data (4KB)
; Exit:  HL = byte read (0x0000-0x00FF) or 0xFFFF if buffer empty
; Notes: Uses 12-bit circular index (0xFFF mask = 4KB buffer)
;        Decrements byte count after successful read
; ===========================================================================
RingBuf_ReadByte:
	cpmi16 (xwa + 4), 0x0
	jr z, LABEL_034D21
	lda xbc, (xwa + 2)
	ld de, (xbc)
	incm 1, (xbc)
	and de, 0xFFF
	ld bc, de
	extz xbc
	inc 6, xbc
	add xbc, xwa
	ld c, (xbc)
	extz bc
	ld hl, bc
	decm 1, (xwa + 4)
	jr LABEL_034D24

LABEL_034D21:
	ldw hl, 0xFFFF

LABEL_034D24:
	ret

LABEL_034D25:
	.byte 0xf1, 0x0d, 0x2b, 0x30, 0x68, 0xd1

RingBuf_SkipToEnd:
	push xiz
	ld xiz, xwa
	ld xwa, xiz
	calr RingBuf_ReadByte
	cps hl, 0
	jr lt, LABEL_034D40

LABEL_034D37:
	ld xwa, xiz
	calr RingBuf_ReadByte
	cps hl, 0
	jr ge, LABEL_034D37

LABEL_034D40:
