	and bc, 0xFFF
	ldada xwa, 11027
	extz xbc
	add xbc, xwa
	ld xwa, (xsp + 6)
	ld a, (xwa)
	ld (xbc), a
	incdi16 1, 11025
	dec 1, de
	lds32 xwa, 1
	add (xsp + 6), xwa
	cps de, 0
	jr nz, Audio_CmdHandler_00_1F_Loop

Audio_CmdHandler_00_1F_Done:
	lds hl, 0
	ret

