; ----------------------------------------------------------------------------
; DSP_Send_Command - Send a command byte to DSP chip
; Entry: BC = chip number (0=DSP1, 1=DSP2)
;        A  = command byte to send
; Exit:  HL = 0 on success, 1 on timeout
; Notes: Polls DSP status with timeout of 0x1F40 iterations (~8000)
;        Writes command byte to port PZ when DSP is ready
; ----------------------------------------------------------------------------
DSP_Send_Command:	; 036331h
	dec 8, xsp
	pushw iz
	ld (xsp + 6), bc	; Save chip number
	ld (xsp + 8), a	; Save command byte
	ldmw (xsp + 4), 0x0	; Result = success
	ldmw (xsp + 2), 0x1F40	; Timeout counter
	ei 6
	call 0x383BB
	call 0x383B3
	ld wa, (xsp + 6)
	call 0x383BF
	ld wa, (xsp + 6)
	call 0x383F7
	ld iz, hl
	ld wa, (xsp + 6)
	call 0x383DB
	ei 0
	cps iz, 0
	jr nz, DSP_Send_Cmd_Ready

DSP_Send_Cmd_WaitLoop:
	ld wa, (xsp + 2)	; Get timeout counter
	decm 1, (xsp + 2)	; Decrement
	cps wa, 0
	jr nz, DSP_Send_Cmd_Poll
	ldmw (xsp + 4), 0x1	; Timeout - set error
	jr DSP_Send_Cmd_Cleanup

DSP_Send_Cmd_Poll:
	ei 6
	call 0x383BB
	call 0x383B3
	ld wa, (xsp + 6)
	call 0x383BF
	ld wa, (xsp + 6)
	call 0x383F7
	ld iz, hl
	ld wa, (xsp + 6)
	call 0x383DB
	ei 0
	cps iz, 0
	jr z, DSP_Send_Cmd_WaitLoop	; Still not ready, keep waiting

DSP_Send_Cmd_Ready:
	ei 6
	ld wa, (xsp + 6)
	call 0x383DB
	call 0x383BB
	call 0x383AF
	call 0x383A7
	ld wa, (xsp + 6)
	call 0x383BF
	ld wa, (xsp + 6)
	call 0x383F7
	cps hl, 0
	jr z, DSP_Send_Cmd_Error
	ld a, (xsp + 8)	; Get command byte
	dd82 0x68, 0x41	; Write to DSP data port
	jr DSP_Send_Cmd_Cleanup

DSP_Send_Cmd_Error:
	ldmw (xsp + 4), 0x1	; Set error flag

DSP_Send_Cmd_Cleanup:
	ld wa, (xsp + 6)
	call 0x383DB
	call 0x383B3
	call 0x383AB
	ei 0
	ldada_24 xwa, 74247
	call 0x38365
	ld a, (xsp + 8)
	extz wa
	call 0x3836C
	ldada_24 xwa, 74250
	call 0x38365
	ld hl, (xsp + 4)	; Return result
	popw iz
	inc 8, xsp
	ret

