; ----------------------------------------------------------------------------
; DSP_Send_Data - Send a data byte to DSP chip
; Entry: BC = chip number (0=DSP1, 1=DSP2)
;        A  = data byte to send
; Exit:  HL = 0 on success, 1 on timeout
; Notes: Similar to DSP_Send_Command but uses data mode
; ----------------------------------------------------------------------------
DSP_Send_Data:	; 0367EEh
	dec 8, xsp
	pushw iz
	ld (xsp + 6), bc	; Save chip number
	ld (xsp + 8), a	; Save data byte
	ldmw (xsp + 4), 0x0	; Result = success
	ldmw (xsp + 2), 0x1F40	; Timeout counter
	ei 6
	call 0x383BB
	call 0x383B3
	ld wa, (xsp + 6)
	call 0x383BF
	ld wa, (xsp + 6)
	call 0x383F7
	ld iz, hl
	ld wa, (xsp + 6)
	call 0x383DB
	ei 0
	cps iz, 0
	jr nz, DSP_Send_Data_Ready

DSP_Send_Data_WaitLoop:
	ld wa, (xsp + 2)
	decm 1, (xsp + 2)
	cps wa, 0
	jr nz, DSP_Send_Data_Poll
	ldmw (xsp + 4), 0x1	; Timeout error
	jr DSP_Send_Data_Cleanup

DSP_Send_Data_Poll:
	ei 6
	call 0x383BB
	call 0x383B3
	ld wa, (xsp + 6)
	call 0x383BF
	ld wa, (xsp + 6)
	call 0x383F7
	ld iz, hl
	ld wa, (xsp + 6)
	call 0x383DB
	ei 0
	cps iz, 0
	jr z, DSP_Send_Data_WaitLoop

DSP_Send_Data_Ready:
	ei 6
	call 0x383AB	; Set data mode (unlike command routine)
	ld wa, (xsp + 6)
	call 0x383DB
	call 0x383BB
	call 0x383AF
	ld wa, (xsp + 6)
	call 0x383BF
	ld wa, (xsp + 6)
	call 0x383F7
	cps hl, 0
	jr z, DSP_Send_Data_Error
	ld a, (xsp + 8)	; Get data byte
	dd82 0x68, 0x41	; Write to DSP data port
	jr DSP_Send_Data_Cleanup

DSP_Send_Data_Error:
	ldmw (xsp + 4), 0x1

DSP_Send_Data_Cleanup:
	ld wa, (xsp + 6)
	call 0x383DB
	call 0x383B3
	ei 0
	ld a, (xsp + 8)
	extz wa
	call 0x3836C
	ldada_24 xwa, 74274
	call 0x38365
	ld hl, (xsp + 4)	; Return result
	popw iz
	inc 8, xsp
	ret

DSP2_Send_Data:
