	ld (xsp + 6), bc
	ld (xsp + 8), a
	ldmw (xsp + 4), 0x0
	ei 6
	ld a, (xsp + 8)
	ldfr_a_berp 0xFB
	ld wa, (xsp + 6)
	call 0x383BF
	ldw iz, 0x8
	cps iz, 0
	jrl le, LABEL_03696A

